import glob
import pandas as pd
import matplotlib.pyplot as plt

# Find CSV files generated by all ONUs
files = glob.glob("report_turnaround_ONU_*.csv")

if not files:
    raise FileNotFoundError(
        "No report_turnaround_ONU_*.csv files found!"
    )

dataframes = []

# Read and combine all ONU measurements
for file in files:
    df = pd.read_csv(file)

    # Preserve original CSV row numbers (header excluded)
    df["CSV_Row_Number"] = range(1, len(df) + 1)
    df["Source_File"] = file

    dataframes.append(df)

data = pd.concat(dataframes, ignore_index=True)

# Remove invalid or missing measurements
data = data.dropna(subset=[
    "reportedBytes",
    "turnAroundTime_s"
])

# Find measurements exceeding 1 ms
threshold = 0.001

exceeded = data[data["turnAroundTime_s"] > threshold]

# Scatter plot
plt.figure(figsize=(10, 6))

plt.scatter(
    data["reportedBytes"],
    data["turnAroundTime_s"],
    s=8,
    alpha=0.5
)

# Mark measurements exceeding 1 ms
plt.scatter(
    exceeded["reportedBytes"],
    exceeded["turnAroundTime_s"],
    s=20,
    color="red",
    label="Turnaround Time > 1 ms"
)

plt.axhline(
    y=threshold,
    color="red",
    linestyle="--",
    label="1 ms threshold"
)

plt.xlabel("Reported Bytes")
plt.ylabel("Turnaround Time (s)")
plt.title("Reported Bytes vs REPORT-to-GATE Turnaround Time")

plt.legend()
plt.grid(True, alpha=0.3)
plt.tight_layout()

plt.savefig(
    "reportedBytes_vs_turnaroundTime.png",
    dpi=300
)

plt.show()

# Print results
print("\n========== TURNAROUND TIME > 1 ms ==========")

print("Total measurements exceeding 1 ms:", len(exceeded))

if not exceeded.empty:
    print(
        exceeded[
            ["Source_File", "CSV_Row_Number",
             "reportedBytes", "turnAroundTime_s"]
        ].to_string(index=False)
    )
else:
    print("No measurements exceeded 1 ms.")

print("\nNumber of ONU files:", len(files))
print("Total measurements:", len(data))
print("Plot saved successfully.")